from fastapi import FastAPI
from pydantic import BaseModel
import ast

app = FastAPI()

class Code(BaseModel):
    code: str

def validate_code(code):
    tree = ast.parse(code)
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            exec(compile(ast.Module(body=[node], type_ignores=[]), "<string>", "exec"), {})

@app.post("/validate")
async def post_validate(code: Code):
    validate_code(code.code)
    return {"ok": True}

import os
from flask import Flask, request

app = Flask(__name__)
CONTENT = "/srv/content"

def untrusted_to_os_path(path):
    return path.strip("/").replace("/", os.sep)

class EditorSession:
    def __init__(self, path):
        self.path = path
    @property
    def fs_path(self):
        return os.path.join(CONTENT, untrusted_to_os_path(self.path))

@app.post("/api/edit")
def edit():
    data = request.get_json()
    ts = EditorSession(data["path"])
    with open(ts.fs_path, "w") as f:
        f.write(data.get("data", ""))
    return {"ok": True}

