import os
from flask import Flask, request

app = Flask(__name__)
MODELS = "/tmp/models"

def validate_model_name(name):
    if not name:
        raise ValueError("invalid name")

@app.post("/registered-models/create")
def create():
    name = request.json["name"]
    validate_model_name(name)
    path = os.path.join(MODELS, name)
    os.makedirs(path)
    return {"ok": True}

from flask import Flask
from flask_restful import Api, Resource, abort

app = Flask(__name__)
api = Api(app)

class Lookup(Resource):
    def get(self, rdtype, domain):
        if rdtype not in ("A", "AAAA", "MX"):
            abort(400, message="%s type is not supported" % rdtype)
        return {"domain": domain}

api.add_resource(Lookup, "/<rdtype>/<domain>")

from flask import Flask, redirect, request
from urllib.parse import urljoin, urlparse

app = Flask(__name__)

def is_safe_url(location):
    ref = urlparse(request.host_url)
    test = urlparse(urljoin(request.host_url, location))
    return test.scheme in ("http", "https") and ref.netloc == test.netloc

@app.route("/login")
def login():
    nxt = request.values.get("next")
    if nxt and is_safe_url(nxt):
        return redirect(nxt)
    return redirect("/dashboard")

import psycopg2
from flask import Flask, request

app = Flask(__name__)

def parse(query):
    return "lower(resource) ~ '%s'" % query

@app.get("/alerts")
def alerts():
    q = request.args.get("q")
    where = "1=1"
    if q:
        where += " AND " + parse(q)
    cur = psycopg2.connect("dbname=alerts").cursor()
    cur.execute("SELECT * FROM alerts WHERE " + where)
    return {"rows": cur.fetchall()}

import subprocess
from fastapi import FastAPI

app = FastAPI()
REPO = "/workspace/repo"

def run(cmd, cwd):
    return subprocess.run(cmd, cwd=cwd, shell=True, capture_output=True, text=True).stdout

@app.get("/git/diff")
def git_diff(path: str):
    return {"diff": run(f'git show "HEAD:{path}"', REPO)}

from django import shortcuts
from django.views import generic

class WorkflowView(generic.TemplateView):
    template_name = "workflow.html"
    redirect_param_name = "next"

    def get_context_data(self, **kwargs):
        ctx = super().get_context_data(**kwargs)
        ctx["REDIRECT_URL"] = self.request.GET.get(self.redirect_param_name)
        return ctx

    def post(self, request, *args, **kwargs):
        next_url = request.POST.get(self.redirect_param_name)
        return shortcuts.redirect(next_url or "/")

import json
from django import forms
from django.shortcuts import render

def build_fields(template_validate):
    fields = {}
    for key, param in template_validate["parameters"].items():
        fields[key] = forms.CharField(
            label=param.get("Label", key),
            help_text=param.get("Description", ""),
        )
    return fields

def launch(request):
    fields = build_fields(json.loads(request.POST["template"]))
    Form = type("F", (forms.Form,), fields)
    return render(request, "launch.html", {"form": Form()})
